def decide(recipient_reputation, round_num, my_history):
    # First few rounds: be generous (cooperate with almost everyone)
    if round_num <= 3:
        threshold = -0.1  # nearly all reputations exceed this
    else:
        # Use personal history to adjust threshold.
        # Count how many times I chose action 'A' (presumed cooperative).
        total = len(my_history)
        if total == 0:
            coop_rate = 0.0
        else:
            coop_actions = sum(1 for entry in my_history if entry['action'] == 'A')
            coop_rate = coop_actions / total
        # If I have been cooperating often, become more trusting (lower threshold)
        # otherwise become stricter (higher threshold)
        if coop_rate > 0.5:
            threshold = 0.1
        else:
            threshold = 0.4
    return recipient_reputation > threshold

