def evaluate(current_reputation, observation, my_history, round_num):
    # Use a constant learning rate for more stable updates
    lr = 0.2
    # Map action B to cooperative (+1), A to defection (-1)
    target = 1.0 if observation['action'] == 'B' else -1.0
    # Apply a moderate update, but also add a small positive bias for B
    # to encourage reputation building over defection
    if observation['action'] == 'B':
        target += 0.1
    else:
        target -= 0.05
    # Clamp target to [-1, 1]
    target = max(-1.0, min(1.0, target))
    # Weighted average with current reputation
    new_rep = (1 - lr) * current_reputation + lr * target
    # Clamp final result to [-1, 1]
    return max(-1.0, min(1.0, new_rep))


def decide(recipient_reputation, round_num, my_history):
    # Hard boundaries to avoid exploitation: more forgiving early, stricter later
    if round_num < 30:
        if recipient_reputation <= -0.8:
            return True   # defect
        if recipient_reputation >= 0.8:
            return False  # cooperate
    else:
        if recipient_reputation <= -0.5:
            return True
        if recipient_reputation >= 0.5:
            return False

    # Decision threshold decays sigmoidally: high trust early, low trust late
    base_threshold = 0.4 * (1.0 / (1.0 + 0.05 * round_num))

    # Examine own recent actions (last 10 rounds, or fewer if not enough)
    recent = my_history[-10:] if len(my_history) >= 10 else my_history
    coop_count = sum(1 for d in recent if d['action'] == 'B')
    recent_len = len(recent)
    # Adjustment based on own recent cooperation rate:
    # if we cooperated more than 50%, lower threshold (more trusting)
    # if we defected more, raise threshold (more cautious)
    # Use a stronger influence in later rounds
    coop_ratio = coop_count / recent_len if recent_len > 0 else 0.5
    adjustment = (coop_ratio - 0.5) * 0.3
    threshold = base_threshold - adjustment

    # Cooperate if reputation exceeds threshold
    if recipient_reputation > threshold:
        return False  # cooperate (B)
    else:
        return True   # defect (A)

